    vector<pair<int, int>> mackerels;
    vector<pair<int, int>> sardines;
    for (int i = 0; i < 2 * N; ++i) {
        int x, y;
        cin >> x >> y;
        if (i < N) {
            mackerels.emplace_back(x, y);
        } else {
            sardines.emplace_back(x, y);
        }
    }

    // Compute initial rectangle for mackerels
    int x_left = numeric_limits<int>::max();
    int x_right = numeric_limits<int>::min();
    int y_bottom = numeric_limits<int>::max();
    int y_top = numeric_limits<int>::min();

    for (const auto& p : mackerels) {
        x_left = min(x_left, p.first);
        x_right = max(x_right, p.first);
        y_bottom = min(y_bottom, p.second);
        y_top = max(y_top, p.second);
    }

    // Check sardines in initial rectangle
    vector<pair<int, int>> s_in_initial;
    for (const auto& s : sardines) {
        if (s.first >= x_left && s.first <= x_right && s.second >= y_bottom && s.second <= y_top) {
            s_in_initial.push_back(s);
        }
    }
    int initial_sardines = s_in_initial.size();

    if (initial_sardines == 0) {
        // Output the initial rectangle
        cout << 4 << endl;
        cout << x_left << " " << y_bottom << endl;
        cout << x_right << " " << y_bottom << endl;
        cout << x_right << " " << y_top << endl;
        cout << x_left << " " << y_top << endl;
        return 0;
    }

    // Otherwise, try to adjust the rectangle to exclude sardines
    int best_score = N - initial_sardines; // a - b for initial rectangle
    int best_x_left = x_left;
    int best_x_right = x_right;
    int best_y_bottom = y_bottom;
    int best_y_top = y_top;

    for (const auto& s : s_in_initial) {
        int sx = s.first;
        int sy = s.second;

        // Try to move right boundary to s.x - 1
        int new_x_left = x_left;
        int new_x_right = sx - 1;
        if (new_x_left < new_x_right && y_bottom < y_top) {
            int a_new = 0;
            int b_new = 0;
            for (const auto& m : mackerels) {
                if (m.first >= new_x_left && m.first <= new_x_right && m.second >= y_bottom && m.second <= y_top) {
                    a_new++;
                }
            }
            for (const auto& s2 : sardines) {
                if (s2.first >= new_x_left && s2.first <= new_x_right && s2.second >= y_bottom && s2.second <= y_top) {
                    b_new++;
                }
            }
            int score = a_new - b_new;
            if (score > best_score) {
                best_score = score;
                best_x_left = new_x_left;
                best_x_right = new_x_right;
                best_y_bottom = y_bottom;
                best_y_top = y_top;
            }
        }

        // Try to move left boundary to s.x + 1
        int new_left = sx + 1;
        int new_right = x_right;
        if (new_left < new_right && y_bottom < y_top) {
            int a_new = 0;
            int b_new = 0;
            for (const auto& m : mackerels) {
                if (m.first >= new_left && m.first <= new_right && m.second >= y_bottom && m.second <= y_top) {
                    a_new++;
                }
            }
            for (const auto& s2 : sardines) {
                if (s2.first >= new_left && s2.first <= new_right && s2.second >= y_bottom && s2.second <= y_top) {
                    b_new++;
                }
            }
            int score = a_new - b_new;
            if (score > best_score) {
                best_score = score;
                best_x_left = new_left;
                best_x_right = new_right;
                best_y_bottom = y_bottom;
                best_y_top = y_top;
            }
        }

        // Try to move top boundary to s.y - 1
        int new_y_top = sy - 1;
        if (new_y_top > y_bottom) {
            if (best_x_left < best_x_right && y_bottom < new_y_top) {
                int a_new = 0;
                int b_new = 0;
                for (const auto& m : mackerels) {
                    if (m.first >= best_x_left && m.first <= best_x_right && m.second >= y_bottom && m.second <= new_y_top) {
                        a_new++;
                    }
                }
                for (const auto& s2 : sardines) {
                    if (s2.first >= best_x_left && s2.first <= best_x_right && s2.second >= y_bottom && s2.second <= new_y_top) {
                        b_new++;
                    }
                }
                int score = a_new - b_new;
                if (score > best_score) {
                    best_score = score;
                    best_y_top = new_y_top;
                }
            }
        }

        // Try to move bottom boundary to s.y + 1
        int new_y_bottom = sy + 1;
        if (new_y_bottom < y_top) {
            if (best_x_left < best_x_right && new_y_bottom < y_top) {
                int a_new = 0;
                int b_new = 0;
                for (const auto& m : mackerels) {
                    if (m.first >= best_x_left && m.first <= best_x_right && m.second >= new_y_bottom && m.second <= y_top) {
