int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    int N;
    cin >> N;

    vector<pair<int, int>> mackerels;
    vector<pair<int, int>> sardines;

    for (int i = 0; i < N; ++i) {
        int x, y;
        cin >> x >> y;
        mackerels.push_back({x, y});
    }

    for (int i = 0; i < N; ++i) {
        int x, y;
        cin >> x >> y;
        sardines.push_back({x, y});
    }

    // Sort mackerels by x, then y
    sort(mackerels.begin(), mackerels.end());
    // Sort sardines by x, then y
    sort(sardines.begin(), sardines.end());

    // Find initial M_rect
    int x_min_mack = mackerels[0].first;
    int x_max_mack = mackerels.back().first;
    int y_min_mack = mackerels[0].second;
    int y_max_mack = mackerels.back().second;

    // Count sardines in initial M_rect
    int s_count = 0;
    for (auto &s : sardines) {
        if (s.first >= x_min_mack && s.first <= x_max_mack && 
            s.second >= y_min_mack && s.second <= y_max_mack) {
            s_count++;
        }
    }

    // If no sardines in initial M_rect, output it
    if (s_count == 0) {
        cout << 4 << endl;
        cout << x_min_mack << " " << y_min_mack << endl;
        cout << x_max_mack << " " << y_min_mack << endl;
        cout << x_max_mack << " " << y_max_mack << endl;
        cout << x_min_mack << " " << y_max_mack << endl;
        return 0;
    }

    // Else, find best candidate
    int best_score = max(0, N - s_count + 1);
    int best_x1 = x_min_mack;
    int best_x2 = x_max_mack;
    int best_y1 = y_min_mack;
    int best_y2 = y_max_mack;

    // Process each sardine in the initial M_rect
    vector<pair<int, int>> sardines_in_rect;
    for (auto &s : sardines) {
        if (s.first >= x_min_mack && s.first <= x_max_mack && 
            s.second >= y_min_mack && s.second <= y_max_mack) {
            sardines_in_rect.push_back(s);
        }
    }

    for (auto &s : sardines_in_rect) {
        int x_s = s.first;
        int y_s = s.second;

        // Generate 4 candidate rectangles
        vector<tuple<int, int, int, int>> candidates;

        // Candidate 1: x range [x_min, x_s - 1]
        int x1 = x_min_mack;
        int x2 = x_s - 1;
        if (x1 <= x2) {
            candidates.push_back({x1, x2, y_min_mack, y_max_mack});
        }

        // Candidate 2: x range [x_s + 1, x_max]
        x1 = x_s + 1;
        x2 = x_max_mack;
        if (x1 <= x2) {
            candidates.push_back({x1, x2, y_min_mack, y_max_mack});
        }

        // Candidate 3: y range [y_min, y_s - 1]
        int y1 = y_min_mack;
        int y2 = y_s - 1;
        if (y1 <= y2) {
            candidates.push_back({x_min_mack, x_max_mack, y1, y2});
        }

        // Candidate 4: y range [y_s + 1, y_max]
        y1 = y_s + 1;
        y2 = y_max_mack;
        if (y1 <= y2) {
            candidates.push_back({x_min_mack, x_max_mack, y1, y2});
        }

        for (auto &c : candidates) {
            int x1_c = get<0>(c);
            int x2_c = get<1>(c);
            int y1_c = get<2>(c);
            int y2_c = get<3>(c);

            // Compute a for mackerels
            auto low_mack = lower_bound(mackerels.begin(), mackerels.end(), make_pair(x1_c, 0));
            auto high_mack = upper_bound(mackerels.begin(), mackerels.end(), make_pair(x2_c, 100000));
            int a = 0;
            for (auto it = low_mack; it != high_mack; ++it) {
                if (it->second >= y1_c && it->second <= y2_c) {
                    a++;
                }
            }

            // Compute b for sardines
            auto low_sard = lower_bound(sardines.begin(), sardines.end(), make_pair(x1_c, 0));
            auto high_sard = upper_bound(sardines.begin(), sardines.end(), make_pair(x2_c, 100000));
            int b = 0;
            for (auto it = low_sard; it != high_sard; ++it) {
                if (it->second >= y1_c && it->second <= y2_c) {
                    b++;
                }
            }

            int current_score = max(0, a - b + 1);
            if (current_score > best_score) {
                best_score = current_score;
                best_x1 = x1_c;
                best_x2 = x2_c;
                best_y1 = y1_c;
                best_y2 = y2_c;
            }
        }
    }

    // Output the best rectangle
    cout << 4 << endl;
    cout << best_x1 << " " << best_y1 << endl;
    cout << best_x2 << " " << best_y1 << endl;
    cout << best_x2 << " " << best_y2 << endl;
    cout << best_x1 << " " << best_y2 << endl;

    return 0;
}

