#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
using namespace std;

int main() {
    int N;
    cin >> N;
    vector<pair<int, int>> mackerels, sardines;
    for (int i = 0; i < 2 * N; ++i) {
        int x, y;
        cin >> x >> y;
        if (i < N) {
            mackerels.push_back({x, y});
        } else {
            sardines.push_back({x, y});
        }
    }

    // Compute initial rectangle for mackerels
    int min_x_mack = mackerels[0].first;
    int max_x_mack = mackerels[0].first;
    int min_y_mack = mackerels[0].second;
    int max_y_mack = mackerels[0].second;
    for (auto& p : mackerels) {
        min_x_mack = min(min_x_mack, p.first);
        max_x_mack = max(max_x_mack, p.first);
        min_y_mack = min(min_y_mack, p.second);
        max_y_mack = max(max_y_mack, p.second);
    }

    // Function to count points in a rectangle
    auto count_in_rect = [&](vector<pair<int, int>>& points, int minx, int maxx, int miny, int maxy) -> int {
        int cnt = 0;
        for (auto& p : points) {
            if (p.first >= minx && p.first <= maxx && p.second >= miny && p.second <= maxy) {
                ++cnt;
            }
        }
        return cnt;
    };

    // Initial rectangle
    int initial_minx = min_x_mack, initial_maxx = max_x_mack;
    int initial_miny = min_y_mack, initial_maxy = max_y_mack;
    int count_s_initial = count_in_rect(sardines, initial_minx, initial_maxx, initial_miny, initial_maxy);
    int best_diff = N - count_s_initial;
    int best_minx = initial_minx, best_maxx = initial_maxx;
    int best_miny = initial_miny, best_maxy = initial_maxy;

    // Generate other candidates
    for (auto& s : sardines) {
        int sx = s.first;
        int sy = s.second;

        // Check if s is inside the initial rectangle
        if (sx >= initial_minx && sx <= initial_maxx && sy >= initial_miny && sy <= initial_maxy) {
            // Generate new rectangles to exclude this sardine
            // Case 1: reduce max_x to sx-1
            int new_maxx = sx - 1;
            if (new_maxx >= initial_minx) {
                int cnt_mack = count_in_rect(mackerels, initial_minx, new_maxx, initial_miny, initial_maxy);
                int cnt_sard = count_in_rect(sardines, initial_minx, new_maxx, initial_miny, initial_maxy);
                int diff = cnt_mack - cnt_sard;
                if (diff > best_diff) {
                    best_diff = diff;
                    best_minx = initial_minx;
                    best_maxx = new_maxx;
                    best_miny = initial_miny;
                    best_maxy = initial_maxy;
                }
            }

            // Case 2: increase min_x to sx + 1
            int new_minx = sx + 1;
            if (new_minx <= initial_maxx) {
                int cnt_mack = count_in_rect(mackerels, new_minx, initial_maxx, initial_miny, initial_maxy);
                int cnt_sard = count_in_rect(sardines, new_minx, initial_maxx, initial_miny, initial_maxy);
                int diff = cnt_mack - cnt_sard;
                if (diff > best_diff) {
                    best_diff = diff;
                    best_minx = new_minx;
                    best_maxx = initial_maxx;
                    best_miny = initial_miny;
                    best_maxy = initial_maxy;
                }
            }

            // Case 3: reduce max_y to sy - 1
            int new_maxy = sy - 1;
            if (new_maxy >= initial_miny) {
                int cnt_mack = count_in_rect(mackerels, initial_minx, initial_maxx, initial_miny, new_maxy);
                int cnt_sard = count_in_rect(sardines, initial_minx, initial_maxx, initial_miny, new_maxy);
                int diff = cnt_mack - cnt_sard;
                if (diff > best_diff) {
                    best_diff = diff;
                    best_minx = initial_minx;
                    best_maxx = initial_maxx;
                    best_miny = initial_miny;
                    best_maxy = new_maxy;
                }
            }

            // Case 4: increase min_y to sy + 1
            int new_miny = sy + 1;
            if (new_miny <= initial_maxy) {
                int cnt_mack = count_in_rect(mackerels, initial_minx, initial_maxx, new_miny, initial_maxy);
                int cnt_sard = count_in_rect(sardines, initial_minx, initial_maxx, new_miny, initial_maxy);
                int diff = cnt_mack - cnt_sard;
                if (diff > best_diff) {
                    best_diff = diff;
                    best_minx = initial_minx;
                    best_maxx = initial_maxx;
                    best_miny = new_miny;
                    best_maxy = initial_maxy;
                }
            }
        }
    }

    // Output the best rectangle
    cout << 4 << endl;
    cout << best_minx << " " << best_miny << endl;
    cout << best_maxx << " " << best_miny << endl;
    cout << best_maxx << " " << best_maxy << endl;
    cout << best_minx << " " << best_maxy << endl;

    return 0;
}

