            mackerels.push_back({x, y});
        } else {
            sardines.push_back({x, y});
        }
    }

    // Compute initial rectangle for mackerels
    int min_x_m = INT_MAX;
    int max_x_m = INT_MIN;
    int min_y_m = INT_MAX;
    int max_y_m = INT_MIN;
    for (auto& p : mackerels) {
        min_x_m = min(min_x_m, p.first);
        max_x_m = max(max_x_m, p.first);
        min_y_m = min(min_y_m, p.second);
        max_y_m = max(max_y_m, p.second);
    }

    // Find sardines in the initial rectangle
    vector<pair<int, int>> sardines_in_rect;
    for (auto& p : sardines) {
        if (p.first >= min_x_m && p.first <= max_x_m && p.second >= min_y_m && p.second <= max_y_m) {
            sardines_in_rect.push_back(p);
        }
    }

    // Preprocess sorted_mackerels_x and sorted_sardines_in_rect_x
    vector<pair<int, int>> sorted_mackerels_x = mackerels;
    sort(sorted_mackerels_x.begin(), sorted_mackerels_x.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
        if (a.first != b.first) return a.first < b.first;
        return a.second < b.second;
    });

    vector<pair<int, int>> sorted_sardines_in_rect_x = sardines_in_rect;
    sort(sorted_sardines_in_rect_x.begin(), sorted_sardines_in_rect_x.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
        if (a.first != b.first) return a.first < b.first;
        return a.second < b.second;
    });

    // Precompute sorted_x_m and sorted_y_m
    vector<int> sorted_x_m;
    vector<int> sorted_y_m;
    for (auto& p : sorted_mackerels_x) {
        sorted_x_m.push_back(p.first);
        sorted_y_m.push_back(p.second);
    }

    // Precompute sorted_x_s_in_rect and sorted_y_s_in_rect
    vector<int> sorted_x_s_in_rect;
    vector<int> sorted_y_s_in_rect;
    for (auto& p : sorted_sardines_in_rect_x) {
        sorted_x_s_in_rect.push_back(p.first);
        sorted_y_s_in_rect.push_back(p.second);
    }

    // Sort the y lists
    sort(sorted_y_m.begin(), sorted_y_m.end());
    sort(sorted_y_s_in_rect.begin(), sorted_y_s_in_rect.end());

    // Initial best_diff and best_rect
    int best_diff = N - sardines_in_rect.size();
    tuple<int, int, int, int> best_rect = { min_x_m, max_x_m, min_y_m, max_y_m };

    // Function to compute count_m and count_s for x range [x_left, x_right]
    auto count_m_x = [&](int x_left, int x_right) -> int {
        int low = lower_bound(sorted_x_m.begin(), sorted_x_m.end(), x_left) - sorted_x_m.begin();
        int high = upper_bound(sorted_x_m.begin(), sorted_x_m.end(), x_right) - sorted_x_m.begin();
        return high - low;
    };

    auto count_s_x_in_rect = [&](int x_left, int x_right) -> int {
        int low = lower_bound(sorted_x_s_in_rect.begin(), sorted_x_s_in_rect.end(), x_left) - sorted_x_s_in_rect.begin();
        int high = upper_bound(sorted_x_s_in_rect.begin(), sorted_x_s_in_rect.end(), x_right) - sorted_x_s_in_rect.begin();
        return high - low;
    };

    // Function to compute count_m and count_s for y range [y_left, y_right]
    auto count_m_y = [&](int y_left, int y_right) -> int {
        int low = lower_bound(sorted_y_m.begin(), sorted_y_m.end(), y_left) - sorted_y_m.begin();
        int high = upper_bound(sorted_y_m.begin(), sorted_y_m.end(), y_right) - sorted_y_m.begin();
        return high - low;
    };

    auto count_s_y_in_rect = [&](int y_left, int y_right) -> int {
        int low = lower_bound(sorted_y_s_in_rect.begin(), sorted_y_s_in_rect.end(), y_left) - sorted_y_s_in_rect.begin();
        int high = upper_bound(sorted_y_s_in_rect.begin(), sorted_y_s_in_rect.end(), y_right) - sorted_y_s_in_rect.begin();
        return high - low;
    };

    for (auto& p : sardines_in_rect) {
        int x_s = p.first;
        int y_s = p.second;

        // Adjust left boundary
        int new_x_left = x_s + 1;
        int new_x_right = max_x_m;
        if (new_x_left <= new_x_right) {
            int cnt_m = count_m_x(new_x_left, new_x_right);
            int cnt_s = count_s_x_in_rect(new_x_left, new_x_right);
            int current_diff = cnt_m - cnt_s;
            if (current_diff > best_diff) {
                best_diff = current_diff;
                best_rect = {new_x_left, new_x_right, min_y_m, max_y_m};
            }
        }

        // Adjust right boundary
        int new_x_left_adj = min_x_m;
        int new_x_right_adj = x_s - 1;
        if (new_x_left_adj <= new_x_right_adj) {
            int cnt_m = count_m_x(new_x_left_adj, new_x_right_adj);
            int cnt_s = count_s_x_in_rect(new_x_left_adj, new_x_right_adj);
            int current_diff = cnt_m - cnt_s;
            if (current_diff > best_diff) {
                best_diff = current_diff;
                best_rect = {new_x_left_adj, new_x_right_adj, min_y_m, max_y_m};
            }
        }

        // Adjust bottom boundary
        int new_y_left_adj = y_s + 1;
        int new_y_right_adj = max_y_m;
        if (new_y_left_adj <= new_y_right_adj) {
            int cnt_m = count_m_y(new_y_left_adj, new_y_right_adj);
            int cnt_s = count_s_y_in_rect(new_y_left_adj, new_y_right_adj);
            int current_diff = cnt_m - cnt_s;
            if (current_diff > best_diff) {
                best_diff = current_diff;
                best_rect = {min_x_m, max_x_m, new_y_left_adj, new_y_right_adj};
            }
        }

        // Adjust top boundary
        int new_y_left_adj_top = min_y_m;
        int new_y_right_adj_top = y_s - 1;
        if (new_y_left_adj_top <= new_y_right_adj_top) {
            int cnt_m = count_m_y(new_y_left_adj_top, new_y_right_adj_top);
            int cnt_s = count_s_y_in_rect(new_y_left_adj_top, new_y_right_adj_top);
            int current_diff = cnt_m - cnt_s;
            if (current_diff > best_diff) {
                best_diff = current_diff;
                best_rect = {min_x_m, max_x_m, new_y_left_adj_top, new_y_right_adj_top};
            }
        }
    }

    // Output the best_rect
    int x1 = get<0>(best_rect);
    int x2 = get<1>(best_rect);
    int y1 = get<2>(best_rect);
    int y2 = get<3>(best_rect);

    cout << 4 << endl;
    cout << x1 << ' ' << y1 << endl;
    cout << x2 << ' ' << y1 << endl;
    cout << x2 << ' ' << y2 << endl;
    cout << x1 << ' ' << y2 << endl;
    return 0;
}

