using namespace std;

int main() {
    int N;
    cin >> N;
    vector<pair<int, int>> mackerels, sardines;
    for (int i = 0; i < 2 * N; ++i) {
        int x, y;
        cin >> x >> y;
        if (i < N) {
            mackerels.push_back({x, y});
        } else {
            sardines.push_back({x, y});
        }
    }

    int x_min_m = INT_MAX, x_max_m = INT_MIN;
    int y_min_m = INT_MAX, y_max_m = INT_MIN;
    for (auto p : mackerels) {
        x_min_m = min(x_min_m, p.first);
        x_max_m = max(x_max_m, p.first);
        y_min_m = min(y_min_m, p.second);
        y_max_m = max(y_max_m, p.second);
    }

    int count_s_initial = 0;
    for (auto p : sardines) {
        if (p.first >= x_min_m && p.first <= x_max_m && p.second >= y_min_m && p.second <= y_max_m) {
            count_s_initial++;
        }
    }

    int best_score = max(0, N - count_s_initial + 1);
    int x1 = x_min_m, x2 = x_max_m, y1 = y_min_m, y2 = y_max_m;

    for (auto p : sardines) {
        int xs = p.first, ys = p.second;
        if (xs >= x_min_m && xs <= x_max_m && ys >= y_min_m && ys <= y_max_m) {
            vector<vector<int>> candidates;
            // Adjust x_max to xs - 1
            int new_x_max = xs - 1;
            if (new_x_max >= x_min_m && new_x_max > x_min_m) {
                vector<int> c = {x_min_m, new_x_max, y_min_m, y_max_m};
                candidates.push_back(c);
            }
            // Adjust x_min to xs + 1
            int new_x_min = xs + 1;
            if (new_x_min <= x_max_m && new_x_min < x_max_m) {
                vector<int> c = {new_x_min, x_max_m, y_min_m, y_max_m};
                candidates.push_back(c);
            }
            // Adjust y_max to ys - 1
            int new_y_max = ys - 1;
            if (new_y_max >= y_min_m && new_y_max > y_min_m) {
                vector<int> c = {x_min_m, x_max_m, y_min_m, new_y_max};
                candidates.push_back(c);
            }
            // Adjust y_min to ys + 1
            int new_y_min = ys + 1;
            if (new_y_min <= y_max_m && new_y_min < y_max_m) {
                vector<int> c = {x_min_m, x_max_m, new_y_min, y_max_m};
                candidates.push_back(c);
            }

            for (auto c : candidates) {
                int x1_c = c[0], x2_c = c[1], y1_c = c[2], y2_c = c[3];
                int count_m_new = 0;
                for (auto p_m : mackerels) {
                    if (p_m.first >= x1_c && p_m.first <= x2_c && p_m.second >= y1_c && p_m.second <= y2_c) {
                        count_m_new++;
                    }
                }
                int count_s_new = 0;
                for (auto p_s : sardines) {
                    if (p_s.first >= x1_c && p_s.first <= x2_c && p_s.second >= y1_c && p_s.second <= y2_c) {
                        count_s_new++;
                    }
                }
                int current_score = max(0, count_m_new - count_s_new + 1);
                if (current_score > best_score) {
                    best_score = current_score;
                    x1 = x1_c;
                    x2 = x2_c;
                    y1 = y1_c;
                    y2 = y2_c;
                }
            }
        }
    }

    cout << 4 << endl;
    cout << x1 << " " << y1 << endl;
    cout << x2 << " " << y1 << endl;
    cout << x2 << " " << y2 << endl;
    cout << x1 << " " << y2 << endl;
    return 0;
}

