    int best_x1 = x_min_m, best_x2 = x_max_m, best_y1 = y_min_m, best_y2 = y_max_m;
    int initial_a = countInside(mackerels, best_x1, best_y1, best_x2, best_y2);
    int initial_b = countInside(sardines, best_x1, best_y1, best_x2, best_y2);
